import random
import string
from typing import List, Tuple

# This generator produces UTF-8 Jsonnet source code bytes tailored to exercise
# libjsonnet snippet evaluators and formatters. It focuses on valid, diverse
# constructs: literals, objects, arrays, comprehensions, functions, imports,
# std library, TLAs/ext vars, multi-file outputs, and stream outputs.
#
# Notes for the fuzzer stubs:
# - FUZZ_PARAM_STR is used for both filename and code/key strings. We provide
#   a single buffer; the harness will slice/randomize, but seeding allows some
#   structure to be present anywhere in the buffer.
# - Keys are sanitized in the harness, so we keep them printable.
# - Code length is <= 512 in the harness; we keep total <= 4096.
# - We generate a mix that can be used as:
#   * snippet to evaluate/format
#   * value for jsonnet_ext_code / jsonnet_tla_code
#   * filename-like strings sprinkled inside to be consumed if needed.

IDENT_START = string.ascii_letters + "_"
IDENT_CONT = IDENT_START + string.digits


def _r(rng: random.Random, seq: List[str]) -> str:
    return rng.choice(seq)


def ident(rng: random.Random, min_len=1, max_len=12) -> str:
    n = rng.randint(min_len, max_len)
    s = rng.choice(IDENT_START)
    s += ''.join(rng.choice(IDENT_CONT) for _ in range(n - 1))
    return s


def json_string(rng: random.Random, min_len=0, max_len=24) -> str:
    # Use JSON-style double-quoted with escapes valid for Jsonnet as well.
    base_chars = string.ascii_letters + string.digits + " _-./:@"
    length = rng.randint(min_len, max_len)
    raw = ''.join(rng.choice(base_chars) for _ in range(length))
    # sprinkle escapes
    escapes = ["\\n", "\\t", "\\\"", "\\\\", "\\u263A"]
    if length > 0 and rng.random() < 0.5:
        pos = rng.randint(0, len(raw))
        raw = raw[:pos] + _r(rng, escapes) + raw[pos:]
    return '"' + raw + '"'


def number(rng: random.Random) -> str:
    if rng.random() < 0.4:
        # integer-like
        return str(rng.randint(-100000, 100000))
    else:
        # float-like
        val = rng.uniform(-1e6, 1e6)
        s = f"{val:.6f}"
        if rng.random() < 0.3:
            s += _r(rng, ["e+2", "e-3", "E+5", "E-1"])  # Jsonnet supports JSON numbers
        return s


def bool_null(rng: random.Random) -> str:
    return _r(rng, ["true", "false", "null"])


def array_expr(rng: random.Random, depth: int) -> str:
    if rng.random() < 0.4 and depth < 2:
        # Comprehension
        v = ident(rng)
        src = array_expr(rng, depth + 1) if rng.random() < 0.4 else "[1,2,3]"
        cond = " if %s > 1" % v if rng.random() < 0.6 else ""
        return "[ %s for %s in %s%s ]" % (_simple_expr(rng, depth + 1), v, src, cond)
    else:
        elems = [simple_expr(rng, depth + 1) for _ in range(rng.randint(0, 4))]
        return "[" + ", ".join(elems) + "]"


def object_field_name(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return ident(rng)
    else:
        return json_string(rng)


def object_expr(rng: random.Random, depth: int) -> str:
    fields = []
    # Possibly use sugar, local, assert, and mix of fields/hidden fields
    if rng.random() < 0.3 and depth < 2:
        # Object comprehension-ish via +
        fields.append("[x for x in [1,2,3]]")  # will not be used as field; keep simple
    for _ in range(rng.randint(0, 3)):
        k = object_field_name(rng)
        v = simple_expr(rng, depth + 1)
        vis = '::' if rng.random() < 0.2 else ':'
        fields.append(f"{k} {vis} {v}")
    # Optional assertion
    if rng.random() < 0.3:
        fields.append(f"assert {bool_expr(rng, depth)} : 'bad';")
    # Optional local binding inside object
    if rng.random() < 0.3:
        fields.insert(0, f"local {ident(rng)} = {simple_expr(rng, depth + 1)};")
    return "{ " + ", ".join(fields) + " }"


def bool_expr(rng: random.Random, depth: int) -> str:
    if rng.random() < 0.5:
        return _r(rng, ["true", "false"]) if rng.random() < 0.5 else f"{number(rng)} > 0"
    a = simple_expr(rng, depth + 1)
    b = simple_expr(rng, depth + 1)
    op = _r(rng, ["==", "!=", "<", ">", "<=", ">="])
    return f"({a}) {op} ({b})"


def lambda_expr(rng: random.Random, depth: int) -> str:
    params = [ident(rng) for _ in range(rng.randint(0, 3))]
    body = simple_expr(rng, depth + 1)
    return f"function({', '.join(params)}) {body}"


def import_expr(rng: random.Random) -> str:
    # Use import variants that do not require external files to still parse as valid code.
    # While evaluation may fail, they are valid for formatters and error paths.
    fname_choices = [
        "file.libsonnet", "data.jsonnet", "a/b/c.libsonnet",
        "std.json", "test.json", "//not/a/real/path.libsonnet",
    ]
    f = rng.choice(fname_choices)
    variant = rng.random()
    if variant < 0.4:
        return f"import '{f}'"
    elif variant < 0.7:
        return f"importstr '{f}'"
    else:
        return f"importbin '{f}'"


def call_std_expr(rng: random.Random, depth: int) -> str:
    fn = rng.choice([
        ("std.length", ["[1,2,3]"]),
        ("std.type", ["{a:1}"]),
        ("std.substr", [json_string(rng), "0", "2"]),
        ("std.tonumber", [json_string(rng)]),
        ("std.toString", [number(rng)]),
        ("std.parseJson", [json_string(rng, 2, 8)]),
        ("std.manifestJsonEx", [simple_expr(rng, depth + 1), "{\"manifestBasic\": true}"]),
    ])
    name, args = fn
    return f"{name}({', '.join(args)})"


def multi_output_program(rng: random.Random) -> str:
    # Program that yields an object mapping filenames to JSON, suitable for *_multi APIs.
    # Use deterministic names and varied values.
    files = []
    for i in range(rng.randint(1, 3)):
        k = json_string(rng, 3, 10)
        v = simple_expr(rng, 1)
        files.append(f"{k}: {v}")
    return "{ " + ", ".join(files) + " }"


def stream_program(rng: random.Random) -> str:
    # Program that evaluates to an array of objects (stream-style).
    elems = [object_expr(rng, 1) for _ in range(rng.randint(1, 4))]
    return "[" + ", ".join(elems) + "]"


def _simple_expr(rng: random.Random, depth: int) -> str:
    # Helper for array comprehension element; choose primitives
    choice = rng.random()
    if choice < 0.35:
        return number(rng)
    elif choice < 0.7:
        return json_string(rng)
    else:
        return bool_null(rng)


def simple_expr(rng: random.Random, depth: int = 0) -> str:
    if depth > 3:
        return _simple_expr(rng, depth)
    choice = rng.random()
    if choice < 0.15:
        return number(rng)
    if choice < 0.30:
        return json_string(rng)
    if choice < 0.42:
        return bool_null(rng)
    if choice < 0.57:
        return array_expr(rng, depth)
    if choice < 0.72:
        return object_expr(rng, depth)
    if choice < 0.82:
        return lambda_expr(rng, depth)
    if choice < 0.90:
        return call_std_expr(rng, depth)
    else:
        return import_expr(rng)


def program_variants(rng: random.Random) -> List[str]:
    # Assemble multiple Jsonnet snippets separated by newlines; the harness picks slices.
    # Include constructs that interact with tla/ext vars, locals, assertions, and functions.
    pieces: List[str] = []

    # 1. Simple evaluable expression
    pieces.append(simple_expr(rng, 0))

    # 2. Object with locals, assertions, and function call
    k1, k2 = ident(rng), ident(rng)
    pieces.append(
        (
            f"local {k1} = {number(rng)};\n"
            f"local {k2} = {json_string(rng)};\n"
            f"{{ a: {k1}, b: {k2}, c: std.toString({k1}), d: [{k1}, {k1}+1] }}"
        )
    )

    # 3. Function with parameters and invocation
    p1, p2 = ident(rng), ident(rng)
    pieces.append(
        f"(function({p1}, {p2}) {{ sum: {p1} + {p2}, ok: {p1} >= 0 }})({rng.randint(0,10)}, {rng.randint(0,10)})"
    )

    # 4. Use of std.native and ext/tla vars (as code references); valid even if not bound
    ext_k = ident(rng)
    tla_k = ident(rng)
    pieces.append(f"{{ ext: std.extVar('{ext_k}'), arg: std.extVar('{tla_k}') }}")

    # 5. Multi-output style object
    pieces.append(multi_output_program(rng))

    # 6. Stream style output
    pieces.append(stream_program(rng))

    # 7. Imports and strings
    pieces.append(f"{{ imported: {import_expr(rng)}, s: {json_string(rng)} }}")

    # 8. Comprehensions and conditionals
    v = ident(rng)
    pieces.append(f"[ {v} * 2 for {v} in [1,2,3,4] if {v} % 2 == 0 ]")

    # 9. Nested objects/arrays
    pieces.append("{ nested: [{x:1},{y:2}], flag: true, n: 0 }")

    return pieces


def filename_like(rng: random.Random) -> str:
    # Provide a plausible short filename string for error messages
    names = ["snippet.libsonnet", "main.jsonnet", "test.libsonnet", "a/b/c.jsonnet"]
    return rng.choice(names)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Build a composite buffer with segments. Each segment is NUL-separated so
    # that FUZZ_PARAM_STR calls can slice into interesting regions regardless of
    # how the engine carves the input.
    segments: List[str] = []

    # Add several filename-like tokens (<= 32 chars) to satisfy fname inputs.
    for _ in range(3):
        segments.append(filename_like(rng))

    # Add several identifier keys (<=32) to serve as keys for ext/tla code.
    for _ in range(4):
        segments.append(ident(rng, 1, 10))

    # Add multiple valid Jsonnet snippets, each under ~512 chars.
    for prog in program_variants(rng):
        # Ensure each program is not too large
        if len(prog) > 500:
            prog = prog[:500]
        segments.append(prog)

    # Also include small standalone valid fragments that can be concatenated
    # or used alone as code strings for *_code bindings.
    fragments = [
        "{x:1,y:2}",
        "[1,2,3]",
        "true",
        "null",
        "std.toString(123)",
        "local a=1; a+2",
        "{ 'file.json': {a:1}, 'other': [1,2] }",
        "function(x) x+1",
    ]
    rng.shuffle(fragments)
    segments.extend(fragments)

    # Join with NULs and ensure overall size <= 4096 bytes.
    blob = ("\x00".join(segments)).encode("utf-8")
    if len(blob) > 4096:
        blob = blob[:4096]
    return blob
